def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024*1024), b""):
            h.update(chunk)
    return h.hexdigest()

def mask(s, head=3, tail=3):
    if s is None:
        return "<None>"
    if not isinstance(s, str):
        s = str(s)
    n = len(s)
    if n == 0:
        return "<empty>"
    if n <= 8:
        return f"<len={n}>"
    if n <= 16:
        return f"{s[:1]}…{s[-1:]} <len={n}>"
    return f"{s[:head]}…{s[-tail:]} <len={n}>"

def charset(s):
    bits=[]
    if re.search(r"[a-z]", s): bits.append("L")
    if re.search(r"[A-Z]", s): bits.append("U")
    if re.search(r"[0-9]", s): bits.append("D")
    if re.search(r"_", s): bits.append("US")
    if re.search(r"-", s): bits.append("HY")
    if re.search(r"[+/=]", s): bits.append("B64")
    if re.search(r"\s", s): bits.append("WS")
    if re.search(r"[^A-Za-z0-9_\-+/=.\s:]", s): bits.append("OTH")
    return "+".join(bits) or "NONE"

