def shannon(s):
    if not s: return 0.0
    n=len(s); c=Counter(s)
    return -sum((v/n)*math.log2(v/n) for v in c.values())

def is_peak_identifier(s):
    t=s.strip().strip("`\"'")
    if SCREAMING.fullmatch(t) or SCREAMING_HY.fullmatch(t):
        return True
    # pau:..:PASS:N
    if re.fullmatch(r"pau:\d+:\d+:\d+:PASS:\d+", t):
        return True
    # path-like docs
    if t.startswith("docs/") or t.startswith("src/") or t.startswith("/Users/"):
        return True
    return False

def is_nonsecret_value(val):
    v = val.strip().strip("\"'")
