        return True
    if re.fullmatch(r"\d+", v):
        return True
    if re.fullmatch(r"(?i)true|false|yes|no|on|off", v):
        return True
    if re.fullmatch(r"(?i)btc-usdt-swap|[A-Z0-9]{2,10}-[A-Z0-9]{2,10}-SWAP", v):
