    return False

def looks_credential_value(val):
    v = val.strip().strip("\"'")
    if is_nonsecret_value(v):
        return False
    if len(v) < 8:
        return False
    # mixed random token: letters+digits, not mostly underscores
    if v.count("_") >= 2 and v.upper() == v:
        return False  # CONSTANT_NAME
    if re.fullmatch(r"[A-Za-z0-9_\-+/=]{16,}", v) and shannon(v) >= 3.8:
        has_l = bool(re.search(r"[a-z]", v))
        has_u = bool(re.search(r"[A-Z]", v))
        has_d = bool(re.search(r"[0-9]", v))
        # real keys often mixed case; screaming snake already excluded
        if has_d and (has_l or has_u):
            return True
    return False

