            walk(v, parts+[k], ref, k)
    elif isinstance(node, list):
        for i,v in enumerate(node):
            walk(v, parts+[i], parent, jkey)
    elif isinstance(node, str):
        pfad=""
        for p in parts:
            pfad += f"[{p}]" if isinstance(p,int) else (("." if pfad else "")+str(p))
        scan_str(node, pfad, ref, jkey)

